-- Authorized scope: 19 physical inputs and 10 kg-to-g aliases. Reference consumed on success.
BEGIN;
SET LOCAL lock_timeout = '5s';

SET LOCAL statement_timeout = '20s';

LOCK TABLE public.products, public.categories, public.product_import_aliases, public.historical_import_records, public.operational_audit_events IN SHARE ROW EXCLUSIVE MODE;

DO $guard$ BEGIN
IF current_database() <> 'neondb' THEN RAISE EXCEPTION 'Unexpected database'; END IF;
IF (SELECT count(*) FROM public.products) <> 17 OR EXISTS (SELECT 1 FROM public.products WHERE product_type <> 'finished_product' OR sku NOT BETWEEN 'PROD001' AND 'PROD017') THEN RAISE EXCEPTION 'Catalog changed; reconcile before import'; END IF;
IF EXISTS (SELECT 1 FROM public.product_import_aliases) THEN RAISE EXCEPTION 'Aliases are no longer empty'; END IF;
IF EXISTS (SELECT 1 FROM public.historical_import_records WHERE source_key='CATALOG-INPUTS-2026-10-18-001' OR source_hash='5702cb91703dce2df2d60305ea0fa647d9190ee12ed30aa336a2ad3014314a23') THEN RAISE EXCEPTION 'Reference/hash consumed'; END IF;
END $guard$;

CREATE TEMP TABLE catalog_inputs_before ON COMMIT DROP AS SELECT 'product' AS kind, to_jsonb(p) AS row FROM public.products p UNION ALL SELECT 'category',to_jsonb(c) FROM public.categories c UNION ALL SELECT 'receipt',to_jsonb(r) FROM public.historical_import_records r UNION ALL SELECT 'audit',to_jsonb(a) FROM public.operational_audit_events a;


DO $guard$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.categories WHERE name='Insumos do workbook' AND is_active) THEN RAISE EXCEPTION 'Input category unavailable'; END IF; END $guard$;






DO $guard$ BEGIN
IF (SELECT count(*) FROM public.products) <> 36 THEN RAISE EXCEPTION 'Product count mismatch'; END IF;
IF (SELECT count(*) FROM jsonb_to_recordset('[{"sku": "INS001", "name": "Açúcar", "category": null, "type": "ingredient", "unit": "g", "isActive": true, "salePrice": null, "purchaseUnit": "kg", "quantityMultiplier": "1000.000"}, {"sku": "INS002", "name": "Óleo", "category": null, "type": "ingredient", "unit": "ml", "isActive": true, "salePrice": null, "purchaseUnit": "ml", "quantityMultiplier": "1.000"}, {"sku": "INS003", "name": "Chocolate", "category": null, "type": "ingredient", "unit": "g", "isActive": true, "salePrice": null, "purchaseUnit": "kg", "quantityMultiplier": "1000.000"}, {"sku": "INS004", "name": "Farinha de Trigo", "category": null, "type": "ingredient", "unit": "g", "isActive": true, "salePrice": null, "purchaseUnit": "kg", "quantityMultiplier": "1000.000"}, {"sku": "INS005", "name": "Papel Manteiga (rolo)", "category": null, "type": "packaging", "unit": "m", "isActive": true, "salePrice": null, "purchaseUnit": "m", "quantityMultiplier": "1.000"}, {"sku": "INS006", "name": "Adesivo", "category": null, "type": "packaging", "unit": "unit", "isActive": true, "salePrice": null, "purchaseUnit": "unit", "quantityMultiplier": "1.000"}, {"sku": "INS007", "name": "Embalagem Simples 5x5", "category": null, "type": "packaging", "unit": "unit", "isActive": true, "salePrice": null, "purchaseUnit": "unit", "quantityMultiplier": "1.000"}, {"sku": "INS008", "name": "Embalagem Simples 7x7", "category": null, "type": "packaging", "unit": "unit", "isActive": true, "salePrice": null, "purchaseUnit": "unit", "quantityMultiplier": "1.000"}, {"sku": "INS009", "name": "Embalagem Recheado 5x5", "category": null, "type": "packaging", "unit": "unit", "isActive": true, "salePrice": null, "purchaseUnit": "unit", "quantityMultiplier": "1.000"}, {"sku": "INS010", "name": "Embalagem Recheado 7x7", "category": null, "type": "packaging", "unit": "unit", "isActive": true, "salePrice": null, "purchaseUnit": "unit", "quantityMultiplier": "1.000"}, {"sku": "INS011", "name": "Embalagem Bombom Unitário", "category": null, "type": "packaging", "unit": "unit", "isActive": true, "salePrice": null, "purchaseUnit": "unit", "quantityMultiplier": "1.000"}, {"sku": "INS012", "name": "Embalagem Kit 4 Bombons", "category": null, "type": "packaging", "unit": "unit", "isActive": true, "salePrice": null, "purchaseUnit": "unit", "quantityMultiplier": "1.000"}, {"sku": "INS013", "name": "Brigadeiro (Recheio)", "category": null, "type": "ingredient", "unit": "g", "isActive": true, "salePrice": null, "purchaseUnit": "kg", "quantityMultiplier": "1000.000"}, {"sku": "INS014", "name": "Doce de Leite (Recheio)", "category": null, "type": "ingredient", "unit": "g", "isActive": true, "salePrice": null, "purchaseUnit": "kg", "quantityMultiplier": "1000.000"}, {"sku": "INS015", "name": "Leite Ninho (Recheio)", "category": null, "type": "ingredient", "unit": "g", "isActive": true, "salePrice": null, "purchaseUnit": "kg", "quantityMultiplier": "1000.000"}, {"sku": "INS016", "name": "Creme de Avelã (Recheio)", "category": null, "type": "ingredient", "unit": "g", "isActive": true, "salePrice": null, "purchaseUnit": "kg", "quantityMultiplier": "1000.000"}, {"sku": "INS017", "name": "Goiabada (Recheio)", "category": null, "type": "ingredient", "unit": "g", "isActive": true, "salePrice": null, "purchaseUnit": "kg", "quantityMultiplier": "1000.000"}, {"sku": "INS018", "name": "Maracujá (Recheio)", "category": null, "type": "ingredient", "unit": "g", "isActive": true, "salePrice": null, "purchaseUnit": "kg", "quantityMultiplier": "1000.000"}, {"sku": "INS019", "name": "Chocolate Ao Leite / Branco", "category": null, "type": "ingredient", "unit": "g", "isActive": true, "salePrice": null, "purchaseUnit": "kg", "quantityMultiplier": "1000.000"}]'::jsonb) AS e(sku text,name text,type text,unit text) JOIN public.products p ON p.sku=e.sku JOIN public.categories c ON c.id=p.category_id WHERE p.name=e.name AND p.product_type::text=e.type AND p.measurement_unit::text=e.unit AND p.is_active AND p.sale_price IS NULL AND c.name='Insumos do workbook') <> 19 THEN RAISE EXCEPTION 'Input readback mismatch'; END IF;
IF (SELECT count(*) FROM public.product_import_aliases a JOIN public.products p ON p.id=a.product_id WHERE a.source_id='purchase-kg:'||p.sku AND p.measurement_unit='g' AND a.source_unit='kg' AND a.quantity_multiplier=1000.000) <> 10 THEN RAISE EXCEPTION 'Conversion mismatch'; END IF;
IF (SELECT count(*) FROM public.operational_audit_events WHERE operation_reference='CATALOG-INPUTS-2026-10-18-001') <> 29 THEN RAISE EXCEPTION 'Audit mismatch'; END IF;
IF EXISTS(SELECT row FROM catalog_inputs_before WHERE kind='product' EXCEPT SELECT to_jsonb(p) FROM public.products p) OR EXISTS(SELECT row FROM catalog_inputs_before WHERE kind='category' EXCEPT SELECT to_jsonb(c) FROM public.categories c) OR EXISTS(SELECT row FROM catalog_inputs_before WHERE kind='receipt' EXCEPT SELECT to_jsonb(r) FROM public.historical_import_records r) OR EXISTS(SELECT row FROM catalog_inputs_before WHERE kind='audit' EXCEPT SELECT to_jsonb(a) FROM public.operational_audit_events a) THEN RAISE EXCEPTION 'Existing rows changed'; END IF;
END $guard$;

SELECT 'CATALOG-INPUTS-2026-10-18-001' AS consumed_reference, (SELECT count(*) FROM public.products WHERE sku LIKE 'INS%') AS inputs, (SELECT count(*) FROM public.product_import_aliases) AS conversions, (SELECT count(*) FROM public.stock_movements) AS movements;
COMMIT;
